{"path":"storage.py","content":"import json
from pathlib import Path

from errors import NotFoundError
from models import Task


class Storage:
    """Small JSON-backed task store; this layer alone assigns task IDs."""

    def __init__(self, path):
        self.path = Path(path)
        self.tasks = {}
        self.next_task_id = 1
        if self.path.exists():
            self._load()

    def _load(self):
        data = json.loads(self.path.read_text(encoding="utf-8"))
        self.next_task_id = data["next_task_id"]
        self.tasks = {task["id"]: Task.from_dict(task) for task in data["tasks"]}

    def save(self):
        payload = {"next_task_id": self.next_task_id, "tasks": [task.to_dict() for task in self.tasks.values()]}
        self.path.write_text(json.dumps(payload, sort_keys=True), encoding="utf-8")

    def create(self, task):
        task.id = self.next_task_id
        self.next_task_id += 1
        self.tasks[task.id] = task
        self.save()
        return task

    def get(self, task_id):
        try:
            return self.tasks[task_id]
        except KeyError as exc:
            raise NotFoundError(f"task {task_id} does not exist") from exc

    def update(self, task_id, changes):
        self.get(task_id)
        # Fix: merge partial updates with existing task
        updated = {**self.tasks[task_id].to_dict(), **changes}
        updated_task = Task.from_dict(updated)
        self.tasks[task_id] = updated_task
        self.save()
        return updated_task"}

{"path":"tests/test_update_context.py","content":"from models import Task
from service import TaskService


def test_complete_task_keeps_the_task_fields_its_caller_did_not_send(tmp_path):
    service = TaskService(Storage(tmp_path / "tasks.json"))
    task = service.create_task(3, "Preserve me", "context matters")
    completed = service.complete_task(task.id)
    assert completed.completed is True
    assert completed.project_id == 3
    assert completed.title == "Preserve me"
    assert completed.description == "context matters"


def test_bulk_import_still_replaces_all_fields_for_existing_task(tmp_path):
    service = TaskService(Storage(tmp_path / "tasks.json"))
    task = service.create_task(3, "Old", "old description")
    updated = service.bulk_import([{
        "id": task.id, "project_id": 4, "title": "New", "description": "new description",
        "completed": True, "archived": False,
    }])[0]
    assert updated.to_dict() == {
        "id": task.id, "project_id": 4, "title": "New", "description": "new description",
        "completed": True, "archived": False,
    }
"}

